        sanskritTe: "అగ్రే వామకరేణ కార్ముకవరం బద్ధ్వా శరం దక్షిణే\nతూణీరేణ సమన్వితేన దధతం వీరాసనే సంస్థితమ్ ।\nరత్నోజ్జ్వలకుండలం రుచిరసత్పీతాంబరం సస్మితం\nవందే రామనన్యభక్తసుఖదం వీరాసనస్థం ప్రభుమ్ ॥ 19 ॥",
