    phalashrutiTextTe: "ఈ స్తోత్రాన్ని నిత్యం పఠించే భక్తునికి శ్రీరాముడు సదా రక్షకుడిగా నిలుస్తాడు. పాతకాలన్నీ నశించి, దీర్ఘాయువు, పుత్రపౌత్రాభివృద్ధి, జయం లభిస్తాయి. అకాల మృత్యువు దరిచేరదు.",
