    dhyanamSanskritTe: "ధ్యాయేన్నిత్యం మహేశం రజతగిరినిభం చారుచంద్రావతంసం\nరత్నాకల్పోజ్జ్వలాంగం పరశుమృగవరాభీతిహస్తం ప్రసన్నమ్ ।\nపద్మాసీనం సమంతాత్స్తుతమమరగణైర్వ్యాఘ్రకృత్తిం వసానం\nవిశ్వాద్యం విశ్వవంద్యం నిఖిలభయహరం పంచవక్త్రం త్రినేత్రమ్ ॥",
