    dhyanamHindi:
      "जो चांदी के पर्वत (कैलाश) के समान श्वेत कांति वाले हैं, जिनके मस्तक पर सुंदर अर्धचंद्र सुशोभित है, रत्नों के आभूषणों से जिनका अंग-अंग दीप्तिमान है, जिनके हाथों में परशु, मृग-मुद्रा, वरद और अभय मुद्राएं हैं, जो प्रसन्नमुख कमल पर विराजमान हैं, देवतागण जिनकी स्तुति कर रहे हैं, जो व्याघ्रचर्म धारण किए हुए हैं, जो संपूर्ण सृष्टि के आदि-कारण, बीज-स्वरूप, समस्त भयों को हरने वाले, पंचमुख और त्रिनेत्रधारी हैं, उन देवाधिदेव महेश्वर का मैं नित्य ध्यान करता हूं।",
