        sanskritTe: "విశ్వామరేంద్రపదవిభ్రమదానదక్షమ్\nఆనందహేతురధికం మురవిద్విషోఽపి ।\nఈషన్నిషీదతు మయి క్షణమీక్షణార్థమ్\nఇందీవరోదరసహోదరమిందిరాయాః ॥ 7 ॥",
