        sanskritTe: "ఇష్టా విశిష్టమతయోఽపి యయా దయార్ద్ర-\nదృష్ట్యా త్రివిష్టపపదం సులభం లభంతే ।\nదృష్టిః ప్రహృష్టకమలోదరదీప్తిరిష్టాం\nపుష్టిం కృషీష్ట మమ పుష్కరవిష్టరాయాః ॥ 8 ॥",
