        sanskritTe: "దద్యాద్ దయానుపవనో ద్రవిణామ్బుధారామ్\nఅస్మిన్నకించనవిహంగశిశౌ విషణ్ణే ।\nదుష్కర్మఘర్మమపనీయ చిరాయ దూరం\nనారాయణప్రణయినీనయనాంబువాహః ॥ 9 ॥",
