        sanskritTe: "జనకసుతా హరి ధూప దిజావై ।\nతాకే కాజ బిలంబ న లావై ॥\nజై జై జై కపి కేసరీ నందన ।\nతేహి కే కాజ సంవారహు బందన ॥ 6 ॥",
