        sanskritTe: "అంజని పూత పవనసుత నామా ।\nతవ బల లఖి కాంపై యమ ధామా ॥\nజయ జయ జయ ధుని హోత అకాశా ।\nసుమిరత హోత దుసహ దుఖ నాశా ॥ 7 ॥",
