        sanskritTe: "ఓం చం చం చం చపలా చలంతా ।\nఓం హను హను హను హనుమంతా ॥\nఓం హం హం హాంక దేత కపి చంచల ।\nఓం సం సం సహమి పరానే ఖల-దల ॥ 9 ॥",
        transliteration:
          "Om caṁ caṁ caṁ capalā calantā |\nOm hanu hanu hanu hanumantā ||\nOm haṁ haṁ hāṁka deta kapi cañcala |\nOm saṁ saṁ sahami parāne khala-dala || 9 ||",
