        sanskritTe: "అపనే జన కో తురత ఉబారహు ।\nసుమిరత హోయ ఆనంద హమారహు ॥\nయహ బజరంగ బాణ జేహి మారే ।\nతాహి కహౌ ఫిరి కవన ఉబారే ॥ 10 ॥",
