        sanskritTe: "అవిరలగండగలన్మదమేదురమత్తమత్తంగజరాజపతే\nత్రిభువనభూషణభూతకలానిధిరూపపయోనిధిరాజసుతే ।\nఅయి సుదతీజనలాలసమానసమోహనమన్మథరాజసుతే\nజయ జయ హే మహిషాసురమర్దిని రమ్యకపర్దిని శైలసుతే ॥ 12 ॥",
