        sanskritTe: "కటితటపీతదుకూలవిచిత్రమయూఖతిరస్కృతచంద్రరుచే\nప్రణతసురాసురమౌలిమణిస్ఫురదంsliceలసన్నఖచంద్రరుచే ।\nజితకనకాచలమౌలిసదోర్జితనిర్భరకుంజరకుంభకుచే\nజయ జయ హె మహిషాసురమర్దిని రమ్యకపర్దిని శైలసుతే ॥ 15 ॥",
