        sanskritTe: "విజితసహస్రకరైకసహస్రకరైకసహస్రకరైకనుతే\nకృతసురతారకసంగరతారకసంగరతారకసూనుసుతే ।\nసురథసమాధిసమానసమాధిసమాధిసమాధిసుజాతరతే\nజయ జయ హే మహిషాసురమర్దిని రమ్యకపర్దిని శైలసుతే ॥ 16 ॥",
