        teluguMeaning: "శరత్కాల పూర్ణిమ చంద్రుని వంటి నీ నిర్మల ముఖారవిందాన్ని నిత్యం ధ్యానించే భక్తుడు భోగభాగ్యాల మోహజాలంలో చిక్కుకోడు; పరమశివుని ప్రియసఖీ! నీ కృప వల్ల సిద్ధించనిది ఏమున్నది? సర్వమూ ప్రాప్తిస్తుంది! మహిషాసురుని సంహరించిన ఓ శైలపుత్రీ! నీకు సదా జయ జయధ్వానాలు.",
