    dhyanamSanskritTe: "పద్మాసనస్థాం విపులకటితటీం పద్మపత్రాయతాక్షీం\nగంభీరావర్తనాభిం స్తనభరనమితాం శుభ్రవస్త్రోత్తరీయామ్ ।\nలక్ష్మీం దివ్యైర్గజేంద్రైర్మణిగణఖచితైః స్నాపితాం హేమకుంభైః\nనిత్యం సా పద్మహస్తా మమ వసతు గృహే సర్వమాంగళ్యయుక్తా ॥",
