        sanskritTe: "క్షుత్పిపాసామలాం జ్యేష్ఠామలక్ష్మీం నాశయామ్యహమ్ ।\nఅభూతిమసమృద్ధిం చ సర్వాన్ నిర్ణుద మే గృహాత్ ॥ 8 ॥",
        transliteration:
          "Kṣut-pipāsā-malāṁ jyeṣṭhām-alakṣmīṁ nāśayāmy-aham |\nAbhūtim-asamṛddhiṁ ca sarvān nirṇuda me gṛhāt || 8 ||",
