        transliteration:
          "Ārdrāṁ puṣkariṇīṁ puṣṭiṁ piṅgalāṁ padma-mālinīm |\nCandrāṁ hiraṇmayīṁ lakṣmīṁ jātavedo ma āvaha || 13 ||",
