export function getAllStotrams(): StotramPage[] {
  return STOTRAM_LIST;
}

export function getStotramBySlug(slug: string): StotramPage | undefined {
  return STOTRAM_LIST.find((s) => s.slug === slug);
}

export function getStotramsByCategory(category: string): StotramPage[] {
  if (category === "all") return STOTRAM_LIST;
  return STOTRAM_LIST.filter((s) => s.stotramCategory === category);
}
